{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Methoxsalen, a furanocoumarin sharing the coumarin core, has relatively low systemic bioavailability in humans, suggesting that coumarin-type lactones can undergo extensive first-pass or limited systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Chrysin, a related benzopyrone, has an estimated oral bioavailability of only 0.003–0.02% in humans after a 400 mg dose, affirmatively demonstrating very low F for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cromolyn, a bis-chromone, has approximately 1% systemic bioavailability after oral administration, showing that chromone/coumarin-type oxygen heterocycles can have F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Zonisamide, a small heteroaromatic drug, has virtually complete oral bioavailability in humans, providing an example that small neutral heterocycles can achieve high F, but its structural similarity to coumarin is low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Although the physicochemical prior favors absorption, the closest coumarin-scaffold analogue (methoxsalen) shows low systemic bioavailability in humans, and related benzopyrones (chrysin, cromolyn) have very low oral F. The high-F evidence comes from structurally dissimilar small molecules with low transferability, so F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for coumarin itself is provided.",
    "Methoxsalen's 'relatively low' bioavailability is not explicitly quantified relative to the 20% threshold.",
    "All Morgan similarity scores are below ~0.31, limiting quantitative transferability.",
    "First-pass metabolism of coumarin in humans is not directly measured in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

